export const getBookImages = async (bookName) => {
  const images = [];
  
  if (bookName === 'sham-e-shabistan-e-raza') {
    for (let i = 1; i <= 896; i++) {
      if (bookImages[i]) {
        images.push(bookImages[i]);
      }
    }
  }
  
  return images;
};

